CREATE OR REPLACE FUNCTION public.enroll_qr_device(p_wallet uuid,p_recovery text,p_device text,p_legacy_owned boolean DEFAULT false) RETURNS TABLE(generation integer,mailbox_user uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.device_qr_credentials; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_wallet::text,0)); SELECT * INTO q FROM public.device_qr_credentials WHERE wallet=p_wallet FOR UPDATE; IF FOUND THEN IF q.recovery_hash<>p_recovery OR q.device_hash<>p_device THEN RAISE EXCEPTION 'Private access does not match active device'; END IF; RETURN QUERY SELECT q.generation,q.mailbox_user; RETURN; END IF; IF EXISTS(SELECT 1 FROM public.device_wallet_access WHERE credential_handle=p_wallet) OR EXISTS(SELECT 1 FROM public.users WHERE credential_handle=p_wallet::text) THEN IF NOT p_legacy_owned OR NOT EXISTS(SELECT 1 FROM public.device_wallet_access WHERE credential_handle=p_wallet) OR NOT EXISTS(SELECT 1 FROM public.users WHERE credential_handle=p_wallet::text) THEN RAISE EXCEPTION 'Verified existing ownership required'; END IF; ELSE INSERT INTO public.device_wallet_access(credential_handle,pin_verifier) VALUES(p_wallet,p_recovery); INSERT INTO public.users(credential_handle,trial_expires_at,free_lifetime_activated) VALUES(p_wallet::text,now()+interval '7 days',true); END IF; INSERT INTO public.device_qr_credentials(wallet,recovery_hash,device_hash) VALUES(p_wallet,p_recovery,p_device) RETURNING * INTO q; RETURN QUERY SELECT q.generation,q.mailbox_user; END; $$; REVOKE ALL ON FUNCTION public.enroll_qr_device(uuid,text,text,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.enroll_qr_device(uuid,text,text,boolean) TO service_role;